-- Name: schedule_skips_id_seq; Type: SEQUENCE; Schema: public; Owner: bekup_owner
--

ALTER TABLE public.schedule_skips ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.schedule_skips_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: sessions; Type: TABLE; Schema: public; Owner: bekup_owner
--

CREATE TABLE public.sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token_hash bytea NOT NULL,
    user_id uuid NOT NULL,
    aal smallint DEFAULT 1 NOT NULL,
    stepup_at timestamp with time zone,
    aal2_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    idle_expires_at timestamp with time zone NOT NULL,
    absolute_expires_at timestamp with time zone NOT NULL,
    ip inet,
    user_agent text,
    revoked_at timestamp with time zone,
    mfa_pending boolean DEFAULT false NOT NULL,
    CONSTRAINT sessions_aal_valid CHECK ((aal = ANY (ARRAY[1, 2]))),
    CONSTRAINT sessions_expiry_order CHECK ((idle_expires_at <= absolute_expires_at)),
    CONSTRAINT sessions_mfa_pending_aal1 CHECK (((NOT mfa_pending) OR ((aal = 1) AND (stepup_at IS NULL) AND (aal2_at IS NULL)))),
    CONSTRAINT sessions_token_hash_length CHECK ((octet_length(token_hash) = 32)),
    CONSTRAINT sessions_user_agent_length CHECK ((char_length(user_agent) <= 512))
);

ALTER TABLE public.sessions OWNER TO bekup_owner;

--
-- Name: settings; Type: TABLE; Schema: public; Owner: bekup_owner
--

CREATE TABLE public.settings (
    key text NOT NULL,
    value jsonb DEFAULT 'null'::jsonb NOT NULL,
    secret_enc bytea,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT settings_key_format CHECK ((key ~ '^[a-z][a-z0-9_.]{0,127}$'::text))
);

ALTER TABLE public.settings OWNER TO bekup_owner;

--
-- Name: users; Type: TABLE; Schema: public; Owner: bekup_owner
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email public.citext NOT NULL,
    display_name text DEFAULT ''::text NOT NULL,
    password_hash text,
    role public.user_role DEFAULT 'user'::public.user_role NOT NULL,
    disabled boolean DEFAULT false NOT NULL,
    locked_until timestamp with time zone,
    failed_login_count integer DEFAULT 0 NOT NULL,
    totp_secret_enc bytea,
    totp_last_step bigint,
    email_verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    totp_pending_enc bytea,
    totp_pending_expires_at timestamp with time zone,
    totp_enabled_at timestamp with time zone,
    mfa_failed_count integer DEFAULT 0 NOT NULL,
    mfa_locked_until timestamp with time zone,
    deleted_at timestamp with time zone,
    password_temporary_until timestamp with time zone,
    mfa_reset_at timestamp with time zone,
    CONSTRAINT users_deleted_disabled CHECK (((deleted_at IS NULL) OR disabled)),
    CONSTRAINT users_display_name_length CHECK ((char_length(display_name) <= 200)),
    CONSTRAINT users_email_length CHECK (((char_length((email)::text) >= 3) AND (char_length((email)::text) <= 254))),
    CONSTRAINT users_failed_login_count_nonneg CHECK ((failed_login_count >= 0)),
    CONSTRAINT users_mfa_failed_count_nonneg CHECK ((mfa_failed_count >= 0)),
    CONSTRAINT users_password_hash_length CHECK ((char_length(password_hash) <= 512)),
    CONSTRAINT users_temporary_needs_password CHECK (((password_temporary_until IS NULL) OR (password_hash IS NOT NULL))),
    CONSTRAINT users_totp_enabled_complete CHECK (((totp_secret_enc IS NULL) = (totp_enabled_at IS NULL))),
    CONSTRAINT users_totp_last_step_nonneg CHECK ((totp_last_step >= 0)),
    CONSTRAINT users_totp_pending_complete CHECK (((totp_pending_enc IS NULL) = (totp_pending_expires_at IS NULL))),
    CONSTRAINT users_totp_pending_size CHECK ((octet_length(totp_pending_enc) <= 256)),
    CONSTRAINT users_totp_secret_size CHECK ((octet_length(totp_secret_enc) <= 256))
);

ALTER TABLE public.users OWNER TO bekup_owner;

--
-- Name: webauthn_ceremonies; Type: TABLE; Schema: public; Owner: bekup_owner
--

CREATE TABLE public.webauthn_ceremonies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    data jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT webauthn_ceremonies_data_size CHECK ((octet_length((data)::text) <= 65536)),
    CONSTRAINT webauthn_ceremonies_kind_valid CHECK ((kind = ANY (ARRAY['registration'::text, 'assertion'::text])))
);

ALTER TABLE public.webauthn_ceremonies OWNER TO bekup_owner;

--
-- Name: webauthn_credentials; Type: TABLE; Schema: public; Owner: bekup_owner
--

CREATE TABLE public.webauthn_credentials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    credential_id bytea NOT NULL,
    public_key bytea NOT NULL,
    attestation_type text DEFAULT ''::text NOT NULL,
    attestation_format text DEFAULT ''::text NOT NULL,
    aaguid uuid,
    sign_count bigint DEFAULT 0 NOT NULL,
    transports text[] DEFAULT '{}'::text[] NOT NULL,
    attachment text DEFAULT ''::text NOT NULL,
    user_present boolean DEFAULT false NOT NULL,
    user_verified boolean DEFAULT false NOT NULL,
    backup_eligible boolean DEFAULT false NOT NULL,
    backup_state boolean DEFAULT false NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone,
    sign_count_anomaly_at timestamp with time zone,
    CONSTRAINT webauthn_credentials_attachment_length CHECK ((char_length(attachment) <= 32)),
    CONSTRAINT webauthn_credentials_attestation_format_length CHECK ((char_length(attestation_format) <= 64)),
    CONSTRAINT webauthn_credentials_attestation_type_length CHECK ((char_length(attestation_type) <= 64)),
    CONSTRAINT webauthn_credentials_backup_flags CHECK ((backup_eligible OR (NOT backup_state))),
    CONSTRAINT webauthn_credentials_credential_id_length CHECK (((octet_length(credential_id) >= 16) AND (octet_length(credential_id) <= 1023))),
    CONSTRAINT webauthn_credentials_name_length CHECK (((char_length(name) >= 1) AND (char_length(name) <= 64))),
    CONSTRAINT webauthn_credentials_public_key_length CHECK (((octet_length(public_key) >= 1) AND (octet_length(public_key) <= 4096))),
    CONSTRAINT webauthn_credentials_sign_count_range CHECK (((sign_count >= 0) AND (sign_count <= '4294967295'::bigint))),
    CONSTRAINT webauthn_credentials_transports_count CHECK ((cardinality(transports) <= 16))
);

ALTER TABLE public.webauthn_credentials OWNER TO bekup_owner;

